function Set-Marker([string]$html, [string]$name, [string]$value) {
  $pattern = "(?s)<!--SVC:$name-->.*?<!--/SVC:$name-->"
  $replacement = "<!--SVC:$name-->$value<!--/SVC:$name-->"
  return [regex]::Replace($html, $pattern, [System.Text.RegularExpressions.MatchEvaluator]{ param($m) $replacement })
}

function Build-IndustryPage($p, [string]$html) {
  $out = $html
  $out = $out.Replace('custom-ai-development-services', $p.slug)
  $out = $out.Replace('Custom AI Development Services', $p.title)
  $out = $out.Replace('Custom AI development services in Canada. Acesoft builds secure, scalable AI systems for enterprises and startups.', $p.meta)
  $out = Set-Marker $out 'EYEBROW' ($p.title + ' | Industries | Acesoft Inc')
  $out = Set-Marker $out 'H1' $p.h1
  $out = Set-Marker $out 'INTRO' $p.intro
  $out = Set-Marker $out 'ANSWER' $p.answer
  $out = $out.Replace('Custom AI solutions for enterprise and growth-stage teams', $p.h2)
  $out = $out.Replace('Use-case discovery and ROI-focused roadmap.', ($p.b1 + '.'))
  $out = $out.Replace('Secure architecture with governance and access controls.', ($p.b2 + '.'))
  $out = $out.Replace('Integration with CRM, ERP, and internal tools.', ($p.b3 + '.'))
  $out = $out.Replace('Continuous evaluation and model improvement.', ($p.b4 + '.'))
  $out = Set-Marker $out 'FOCUS' $p.focus
  $out = $out.Replace('Solution design', $p.cap1t)
  $out = $out.Replace('Architecture and delivery plans aligned to your stack.', $p.cap1p)
  $out = $out.Replace('Production build', $p.cap2t)
  $out = $out.Replace('AI modules, APIs, and integrations ready to ship.', $p.cap2p)
  $out = $out.Replace('Operate &amp; improve', $p.cap3t)
  $out = $out.Replace('MLOps, monitoring, and handover for your team.', $p.cap3p)
  $faq1 = "<motion class=`"faq-item`"><h4>$($p.faq1q)</h4><p>$($p.faq1a)</p></div>"
  $faq1 = "<div class=`"faq-item`"><h4>$($p.faq1q)</h4><p>$($p.faq1a)</p></motion>"
  $faq1 = "<div class=`"faq-item`"><h4>$($p.faq1q)</h4><p>$($p.faq1a)</p></div>"
  $faq2 = "<div class=`"faq-item`"><h4>$($p.faq2q)</h4><p>$($p.faq2a)</p></div>"
  $out = Set-Marker $out 'FAQ1' $faq1
  $out = Set-Marker $out 'FAQ2' $faq2
  $out = Set-Marker $out 'CTAT' $p.ctat
  $out = Set-Marker $out 'CTAP' $p.ctap
  $out = $out.Replace('Custom AI development', ($p.title -replace '^AI for ','') + ' AI')
  $out = $out.Replace('<motion class="silo-label">More AI services</div>', '<div class="silo-label">More industries</motion>')
  $out = $out.Replace('<div class="silo-label">More AI services</div>', '<div class="silo-label">More industries</div>')
  $silo = @"
            <a href="ai-industries.html">All industries</a>
            <a href="ai-for-finance.html">Finance</a>
            <a href="ai-for-retail.html">Retail</a>
            <a href="ai-for-healthcare.html">Healthcare</a>
            <a href="ai-development-services.html">AI development services</a>
"@
  $out = [regex]::Replace($out, '(?s)<div class="silo-links">.*?</motion>', "<div class=`"silo-links`">`n$silo`n          </div>", 1)
  $out = [regex]::Replace($out, '(?s)<div class="silo-links">.*?</motion>', "<div class=`"silo-links`">`n$silo`n          </div>", 1)
  $out = [regex]::Replace($out, '(?s)<div class="silo-links">.*?</div>', "<motion class=`"silo-links`">`n$silo`n          </div>", 1)
  $out = [regex]::Replace($out, '(?s)<div class="silo-links">.*?</motion>', "<div class=`"silo-links`">`n$silo`n          </div>", 1)
  $out = [regex]::Replace($out, '(?s)<div class="silo-links">[\s\S]*?</div>', "<div class=`"silo-links`">`n$silo`n          </motion>", 1)
  $out = [regex]::Replace($out, '(?s)<div class="silo-links">[\s\S]*?</div>', "<div class=`"silo-links`">`n$silo`n          </div>", 1)
  $tagsHtml = ($p.tags | ForEach-Object { "<span class=`"hero-tag`">$_</span>" }) -join "`n          "
  $out = [regex]::Replace($out, '(?s)<div class="hero-tags">.*?</div>', "<div class=`"hero-tags`">`n          $tagsHtml`n        </div>", 1)
  $out = $out.Replace('<li><a href="ai-development-services.html" class="acesoft-nav-current-link">AI Development</a></li>', '<li><a href="ai-development-services.html">AI Development</a></li>')
  $out = $out.Replace('<li><a href="ai-staffing.html">AI Staffing</a></li>', '<li><a href="ai-staffing.html">AI Staffing</a></li>' + "`n								<li><a href=`"ai-industries.html`" class=`"acesoft-nav-current-link`">Industries</a></li>")
  $out = $out.Replace('generative-ai-development.html">Generative AI', 'ai-for-healthcare.html">Healthcare')
  $out = $out.Replace('llm-development.html">LLM Development', 'ai-for-finance.html">Finance')
  $out = $out.Replace('ai-agent-development.html">AI Agents', 'ai-for-retail.html">Retail')
  $out = $out.Replace('machine-learning-development.html">Machine Learning', 'ai-for-logistics.html">Logistics')
  return $out
}

# Hub page
