$hub = $hub.Replace('AI Staffing Services | Hire AI Engineers & ML Experts | Acesoft', 'AI Solutions by Industry | Sector-Specific AI | Acesoft')
$hub = $hub.Replace('Scale your team with Acesoft AI staffing services. Hire vetted AI engineers, ML specialists, data scientists, and MLOps experts for flexible delivery.', 'Industry-specific AI solutions for healthcare, finance, retail, logistics, and more. Acesoft builds secure, production-ready AI for your sector in Canada and the USA.')
