$hub = $hub.Replace('Staffing Options', 'Industries We Serve')
$hub = $hub.Replace('Explore AI Staffing &amp; Hiring Services', 'Explore AI Solutions by Industry')
$hub = $hub.Replace('Flexible ways to add AI engineers and teams-each option has a dedicated page with engagement models and how Acesoft can help.', 'Each industry has a dedicated page with use cases, deliverables, and how Acesoft can help your team in Canada and beyond.')
$hub = $hub.Replace('seo-service-grid seo-service-grid--staffing', 'seo-service-grid seo-service-grid--industries')
$hub = $hub.Replace('<li><a href="ai-industries.html" class="acesoft-nav-current-link">AI Staffing</a></li>', '<li><a href="ai-staffing.html">AI Staffing</a></li>' + "`n								<li><a href=`"ai-industries.html`" class=`"acesoft-nav-current-link`">Industries</a></li>")

$hub = [regex]::Replace($hub, '(?s)(<div class="seo-service-grid seo-service-grid--industries">).*?(</div>\s*</motion>\s*</motion>)', "`$1`n$hubCards`n          </div>", 1)
$hub = [regex]::Replace($hub, '(?s)(<motion class="seo-service-grid seo-service-grid--industries">).*?(</div>)', "`$1`n$hubCards`n          `$2", 1)
