$hub = [regex]::Replace($hub, '(?s)<div class="seo-service-grid seo-service-grid--industries">[\s\S]*?</div>\s*</div>', "<div class=`"seo-service-grid seo-service-grid--industries`">`n$hubCards`n          </div>", 1)

