  $insert = "  <url>`n    <loc>https://www.aidevelopers.ca/ai-industries.html</loc>`n  </url>`n"
  foreach ($p in $industries) {
    $insert += "  <url>`n    <loc>https://www.aidevelopers.ca/$($p.slug).html</loc>`n  </url>`n"
  }
  $sitemap = $sitemap.Replace('</urlset>', ($insert + '</urlset>'))
